window.kbPageData["views/entry/k-33f9bebbc50a0920"] = {"key":"entry/k-33f9bebbc50a0920","state":{"route":"entry/k-33f9bebbc50a0920"},"node":{"id":"k-33f9bebbc50a0920","mode":"k","title":"经营者欺诈的惩罚性赔偿","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["经营者欺诈时消费者可以请求惩罚性赔偿"],"qs":["江苏 2025 B类 行测#17"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"经营者提供商品或者服务有欺诈行为的，应按消费者要求增加赔偿。增加赔偿额为商品价款或服务费用的三倍，不足五百元的按五百元计算，法律另有规定的依其规定。","review":{"definition":"经营者提供商品或者服务有欺诈行为的，应按消费者要求增加赔偿。增加赔偿额为商品价款或服务费用的三倍，不足五百元的按五百元计算，法律另有规定的依其规定。","explanation":"题设将M公司对临时密码功能的不实宣传认定为经营者欺诈，韩某可以依《消费者权益保护法》第五十五条第一款主张增加赔偿，因此C项成立。题干未给出购买价款，C项只判断韩某是否有权主张赔偿。","references":[],"evidence":"应当按照消费者的要求增加赔偿其受到的损失","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2025 B类 行测#17":{"paper":"江苏 2025 B类 行测","n":17,"mod":"常识判断","src":["91e0d9fd02ca7ec6d61f.pdf",4],"asrc":["f2ff67a0f2a2f7e8e926.pdf",7],"card":"e4d47d034c952b8ddf91e4bf","links":[{"id":"k-33f9bebbc50a0920","role":"解题依据","why":"经营者提供商品时实施欺诈，触发消费者的增加赔偿请求权。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-33f9bebbc50a0920":[["江苏 2025 B类 行测#17"]]}};
